@layer components {
  @keyframes profile-card-shimmer {
    from {
      transform: translateX(-100%);
      opacity: 0.4;
    }
    to {
      transform: translateX(100%);
      opacity: 0.4;
    }
  }

  .profile-card {
    background-color: var(--shelf-profile-card-bgColor-base);
    border: var(--shelf-borderWidth-thin) solid var(--shelf-profile-card-borderColor-base);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-spacing-md);
  }

  .profile-card-title {
    color: var(--shelf-profile-card-fgColor-title);
    font-size: var(--shelf-fontSize-md);
    font-weight: var(--shelf-fontWeight-semibold);
  }

  .profile-card-subtitle {
    color: var(--shelf-profile-card-fgColor-subtitle);
    font-size: var(--shelf-fontSize-sm);
  }

  /* Skeleton variant */

  .profile-card--skeleton .profile-card-title,
  .profile-card--skeleton .profile-card-subtitle {
    background-color: var(--shelf-profile-card-bgColor-skeleton);
    color: transparent;
    border-radius: var(--shelf-radius-sm);
    overflow: hidden;
    position: relative;
  }

  .profile-card--skeleton .profile-card-subtitle {
    width: 60%;
  }

  .profile-card--skeleton .profile-card-title::after,
  .profile-card--skeleton .profile-card-subtitle::after {
    content: "";
    position: absolute;
    inset: 0;
    background-color: var(--shelf-profile-card-bgColor-shimmer);
    animation: profile-card-shimmer var(--shelf-duration-shimmer) var(--shelf-easing-linear) infinite;
  }
}
